/**
 * @title An inset sidebar with secondary navigation
 * @description The page sits in a raised card beside the sidebar. Main sections, projects, support links and the account menu.
 * @route /dashboard
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { AppSidebar } from "@/components/app-sidebar";
import { SiteHeader } from "@/components/site-header";
import { PagePlaceholder } from "@/components/page-placeholder";

export default function Page() {
  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Projects", href: "#" }, { label: "Design engineering" }]} />
        <PagePlaceholder title="Design engineering" />
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { BookOpen, Bot, Command, Frame, LifeBuoy, Map as MapIcon, PieChart, Send, Settings2, SquareTerminal } from "lucide-react";
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader } from "@/components/ui/sidebar";
import { BrandHeader } from "@/components/brand-header";
import { NavMain } from "@/components/nav-main";
import { NavProjects } from "@/components/nav-projects";
import { NavSecondary } from "@/components/nav-secondary";
import { NavUser } from "@/components/nav-user";

const data = {
  user: { name: "Jane Cooper", email: "jane@acme.com" },
  navMain: [
    { title: "Playground", url: "#", icon: SquareTerminal, isActive: true, items: [{ title: "History", url: "#" }, { title: "Starred", url: "#" }, { title: "Settings", url: "#" }] },
    { title: "Models", url: "#", icon: Bot, items: [{ title: "Genesis", url: "#" }, { title: "Explorer", url: "#" }, { title: "Quantum", url: "#" }] },
    { title: "Documentation", url: "#", icon: BookOpen, items: [{ title: "Introduction", url: "#" }, { title: "Get started", url: "#" }, { title: "Tutorials", url: "#" }] },
    { title: "Settings", url: "#", icon: Settings2, items: [{ title: "General", url: "#" }, { title: "Team", url: "#" }, { title: "Billing", url: "#" }] },
  ],
  navSecondary: [{ title: "Support", url: "#", icon: LifeBuoy }, { title: "Feedback", url: "#", icon: Send }],
  projects: [
    { name: "Design engineering", url: "#", icon: Frame },
    { name: "Sales and marketing", url: "#", icon: PieChart },
    { name: "Travel", url: "#", icon: MapIcon },
  ],
};

export function AppSidebar() {
  return (
    <Sidebar variant="inset" label="Main navigation">
      <SidebarHeader>
        <BrandHeader name="Acme Inc" detail="Enterprise" logo={Command} />
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Main" className="contents">
          <NavMain items={data.navMain} />
          <NavProjects projects={data.projects} />
          <NavSecondary items={data.navSecondary} className="mt-auto" />
        </nav>
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={data.user} />
      </SidebarFooter>
    </Sidebar>
  );
}

"use client";
import { GalleryVerticalEnd, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Logo, product name and a second line (plan or version) at the top of the sidebar. Links home. */
export function BrandHeader({ name = "Acme Docs", detail = "v4.0.0", logo = GalleryVerticalEnd }: { name?: string; detail?: string; logo?: LucideIcon }) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="lg" tooltip={name}>
          <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={logo} size={16} /></span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-label-medium text-fg-primary">{name}</span>
            <span className="truncate text-caption-default">{detail}</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import { ChevronRight, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  SidebarGroup, SidebarGroupLabel, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarMenuSub, SidebarMenuSubButton,
  SidebarMenuSubItem, useDisclosure, useSidebar,
} from "@/components/ui/sidebar";

export type NavItem = { title: string; url: string; icon: LucideIcon; isActive?: boolean; items?: { title: string; url: string; isActive?: boolean }[] };

/** Main navigation: rows that open to show their pages. In the icon rail a row expands the sidebar first. */
export function NavMain({ label = "Platform", items }: { label?: string; items: NavItem[] }) {
  return (
    <SidebarGroup>
      <SidebarGroupLabel>{label}</SidebarGroupLabel>
      <SidebarMenu>
        {items.map((item) => (item.items?.length ? <NavMainGroup key={item.title} item={item} /> : (
          <SidebarMenuItem key={item.title}>
            <SidebarMenuButton href={item.url} isActive={item.isActive} tooltip={item.title}>
              <Icon name={item.icon} />
              <span>{item.title}</span>
            </SidebarMenuButton>
          </SidebarMenuItem>
        )))}
      </SidebarMenu>
    </SidebarGroup>
  );
}

function NavMainGroup({ item }: { item: NavItem }) {
  const d = useDisclosure(item.isActive);
  const { state, setOpen, isMobile } = useSidebar();
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        tooltip={item.title}
        {...d.triggerProps}
        onClick={() => { if (state === "collapsed" && !isMobile) { setOpen(true); d.setOpen(true); } else d.triggerProps.onClick(); }}
      >
        <Icon name={item.icon} />
        <span className="flex-1">{item.title}</span>
        <Icon name={ChevronRight} size={16} className={d.open ? "rotate-90 transition-transform" : "transition-transform"} />
      </SidebarMenuButton>
      <SidebarMenuSub {...d.contentProps}>
        {item.items!.map((sub) => (
          <SidebarMenuSubItem key={sub.title}>
            <SidebarMenuSubButton href={sub.url} isActive={sub.isActive}><span>{sub.title}</span></SidebarMenuSubButton>
          </SidebarMenuSubItem>
        ))}
      </SidebarMenuSub>
    </SidebarMenuItem>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarGroup, SidebarGroupLabel, SidebarMenu, SidebarMenuAction, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** A list of projects, each with a "More" menu. Hidden in the icon rail. */
export function NavProjects({ projects }: { projects: { name: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup className="group-data-[collapsible=icon]/sidebar:hidden">
      <SidebarGroupLabel>Projects</SidebarGroupLabel>
      <SidebarMenu>
        {projects.map((p) => (
          <SidebarMenuItem key={p.name}>
            <SidebarMenuButton href={p.url}>
              <Icon name={p.icon} />
              <span>{p.name}</span>
            </SidebarMenuButton>
            <div className="absolute end-1 top-2 group-data-[collapsible=icon]/sidebar:hidden">
              <Menu
                label={`More actions for ${p.name}`}
                placement="bottom-end"
                items={[{ label: "View project", icon: "folder" }, { label: "Share", icon: "share" }, { label: "Delete project", icon: "trash", tone: "danger", separatorBefore: true }]}
                trigger={({ ref, ...t }) => <SidebarMenuAction ref={ref} {...t} label={`More actions for ${p.name}`} showOnHover className="static" />}
              />
            </div>
          </SidebarMenuItem>
        ))}
        <SidebarMenuItem>
          <SidebarMenuButton className="text-fg-secondary">
            <Icon name="more" />
            <span>More projects</span>
          </SidebarMenuButton>
        </SidebarMenuItem>
      </SidebarMenu>
    </SidebarGroup>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Small links near the bottom of the sidebar (support, feedback). */
export function NavSecondary({ items, ...rest }: HTMLAttributes<HTMLDivElement> & { items: { title: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup {...rest}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton href={item.url} size="sm" tooltip={item.title}>
                <Icon name={item.icon} size={16} />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

/** Stand-in content for a page. Replace it with your own. */
export function PagePlaceholder({ title }: { title: string }) {
  return (
    <div className="flex flex-1 flex-col gap-4 p-4 md:p-6">
      <h1 className="text-heading-h2">{title}</h1>
      <div aria-hidden className="grid gap-4 md:grid-cols-3">
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
      </div>
      <div aria-hidden className="min-h-96 flex-1 rounded-container bg-surface-subtle" />
    </div>
  );
}
